//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-variadic-text.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


#[test]
fn noscript_variadic_text_parent_append_prepend_actual_nodes_raw_strings_and_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,a=document.createTextNode('A\udfff'),b=document.createTextNode('\ud800B'),watch=new MutationObserver(function(){});watch.observe(host,{childList:true});if(host.append(a,'<b>literal</b>',b)!==undefined)throw 'append return';var rs=watch.takeRecords(),literal=a.nextSibling;if(host.firstChild!==old||old.nextSibling!==a||literal.data!=='<b>literal</b>'||literal.nextSibling!==b||b.parentNode!==host||literal.ownerDocument!==document||rs.length!==1||rs[0].addedNodes.length!==3||rs[0].addedNodes[0]!==a||rs[0].addedNodes[1]!==literal||rs[0].addedNodes[2]!==b||rs[0].previousSibling!==old||rs[0].nextSibling!==null)throw 'actual parent append';var c=document.createTextNode('front');if(host.prepend(c,'\udfff\ud800')!==undefined)throw 'prepend return';rs=watch.takeRecords();if(host.firstChild!==c||c.nextSibling.data!=='\udfff\ud800'||c.nextSibling.nextSibling!==old||rs.length!==1||rs[0].addedNodes[0]!==c||rs[0].addedNodes[1]!==c.nextSibling||rs[0].previousSibling!==null||rs[0].nextSibling!==old||document.querySelectorAll('b').length)throw 'actual parent prepend';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_variadic_text_before_after_actual_siblings_and_live_parent_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,a=document.createTextNode('A\udfff'),b=document.createTextNode('\ud800B'),watch=new MutationObserver(function(){}),range=document.createRange();range.setStart(host,1);range.setEnd(host,1);watch.observe(host,{childList:true});if(old.before(a,'before')!==undefined)throw 'before return';var rs=watch.takeRecords(),before=a.nextSibling;if(host.firstChild!==a||before.data!=='before'||before.nextSibling!==old||rs.length!==1||rs[0].addedNodes[0]!==a||rs[0].addedNodes[1]!==before||rs[0].previousSibling!==null||rs[0].nextSibling!==old||range.startContainer!==host||range.startOffset!==3||range.endOffset!==3)throw 'actual before';if(old.after('after',b)!==undefined)throw 'after return';rs=watch.takeRecords();if(old.nextSibling.data!=='after'||old.nextSibling.nextSibling!==b||b.parentNode!==host||a.data!=='A\udfff'||b.data!=='\ud800B'||rs.length!==1||rs[0].addedNodes[0]!==old.nextSibling||rs[0].addedNodes[1]!==b||rs[0].previousSibling!==old||rs[0].nextSibling!==null||range.startOffset!==3||range.endOffset!==3)throw 'actual after';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_variadic_text_replace_with_and_remove_actual_identity_records_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),old=host.firstChild,a=document.createTextNode('a'),b=document.createTextNode('b'),watch=new MutationObserver(function(){}),range=document.createRange();range.setStart(old,1);range.setEnd(old,3);watch.observe(host,{childList:true});if(old.replaceWith(a,'\udfff\ud800',b)!==undefined)throw 'replaceWith return';var rs=watch.takeRecords(),middle=a.nextSibling;if(host.firstChild!==a||middle.data!=='\udfff\ud800'||middle.nextSibling!==b||old.parentNode!==null||old.data!=='held'||rs.length!==1||rs[0].removedNodes[0]!==old||rs[0].addedNodes[0]!==a||rs[0].addedNodes[1]!==middle||rs[0].addedNodes[2]!==b||range.startContainer!==host||range.endContainer!==host||range.startOffset||range.endOffset)throw 'actual replaceWith';if(a.remove()!==undefined)throw 'remove return';rs=watch.takeRecords();if(a.parentNode!==null||a.data!=='a'||host.firstChild!==middle||rs.length!==1||rs[0].removedNodes[0]!==a||rs[0].previousSibling!==null||rs[0].nextSibling!==middle)throw 'actual Text remove';a.remove();if(watch.takeRecords().length)throw 'detached remove no-op';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_variadic_text_single_node_native_and_nontext_guards_refuse_without_tree_prefix(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),text=host.firstChild,guarded=document.getElementById('guard'),blocked=guarded.firstChild,fresh=document.createTextNode('fresh'),span=document.createElement('span'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for code in ["text.before(span);","text.after(blocked);","text.replaceWith(span);","guarded.append(fresh);","guarded.prepend(fresh);","blocked.before(fresh);","blocked.after(fresh);","blocked.replaceWith(fresh);","blocked.remove();"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains("inert resource subtrees"),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||guarded.firstChild!==blocked||fresh.parentNode!==null||span.parentNode!==null||watch.takeRecords().length)throw 'variadic guard prefix';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
